  const a = { slope: 3, intercept: 0 }, b = { slope: 3, intercept: Math.log(10) };
  checkClose("parallel, 10x higher, age 62.5 -> 10", safe(() => shiftToMeet(a, b, 62.5)), 10);
  checkClose("parallel, 10x higher, age 2 -> 10", safe(() => shiftToMeet(a, b, 2)), 10);
