s.push(`<text x="${lx}" y="${yp(h) + 76}" font-size="12" fill="${BLUE}">new ${slope(newG).toFixed(2)} (flat)</text>`);
s.push("</svg>");
const out = path.join(__dirname, "..", "output", "learn", "10-cutoff-bug.svg");
