// --- Page wiring (browser only) -----------------------------------------------
if (typeof document !== "undefined") {
  const $ = (id) => document.getElementById(id);
  const state = { seed: 1, sim: null, simKey: null };
  CI5.cancers.forEach((c, i) => $("cancer").add(new Option(c.name, i)));

  const settings = () => ({ r: Number($("r").value), p: Number($("p").value), N: Number($("N").value), cancer: Number($("cancer").value) });
  const key = (st) => `${st.r}|${st.p}|${st.N}|${state.seed}`;

  /** Redraw everything from the current sliders. The simulation is shown only if it matches them. */
  function render() {
    const st = settings();
    $("rOut").textContent = st.r;
    $("pOut").textContent = st.p.toFixed(4);
    $("NOut").textContent = st.N;
    const sim = state.simKey === key(st) ? state.sim : null;
    const nums = pageNumbers(st.r, st.p, st.N, st.cancer, sim);
    $("lifeOut").textContent = `${(100 * nums.lifetimeRisk).toFixed(1)}%`;
    const simText = nums.simFit
      ? `<span class="sim">Simulated slope ${nums.simFit.slope.toFixed(2)}</span> (R² ${nums.simFit.rSquared.toFixed(3)}, seed ${state.seed})`
      : `<span class="sim">Simulated: press "Run simulation"</span>`;
    const exactText = nums.exactFit ? `Exact slope ${nums.exactFit.slope.toFixed(2)} (simple rule r − 1 = ${st.r - 1})` : "Exact slope: none (no cases from 25 up)";
    $("summary").innerHTML =
      `${simText} &nbsp;·&nbsp; <b>${exactText}</b><br>` +
      `<span class="real">${nums.cancerName}: real slope ${nums.realFit.slope.toFixed(2)}</span> ` +
      `(real 60–64 rate ${per100k(nums.real6064)} per 100,000; drawn ×${nums.k.toPrecision(3)} to meet the model at ${MEET_AGE})`;
    $("logGraph").innerHTML = drawGraph(nums, "log");
    $("plainGraph").innerHTML = drawGraph(nums, "plain");
  }

  /** Run the 20,000-person simulation (about a second), then redraw. */
  function runSim() {
    const st = settings();
    $("status").textContent = "Running…";
    $("run").disabled = true;
    setTimeout(() => {
      const t0 = performance.now();
      state.sim = runReport(M_PEOPLE, st.N, st.r, st.p, state.seed);
      state.simKey = key(st);
      $("status").textContent = `Done in ${Math.round(performance.now() - t0)} ms.`;
      $("run").disabled = false;
      render();
    }, 20);
  }

  for (const id of ["r", "p", "N", "cancer"]) $(id).addEventListener("input", render);
  $("run").addEventListener("click", runSim);
  $("seed").addEventListener("click", () => { state.seed += 1; runSim(); });
  render();
}

if (typeof module !== "undefined") module.exports = { pageNumbers, drawGraph };

