  const fromSlopeAge = sim.groups.filter((g) => g.start >= SLOPE_FROM);
  return {
    largest: z.largest, // {z, start, end} or null
    level,
    sumZ2: z.sumZ2,
    groups: k,
    noiseLow: k - spread,
    noiseHigh: k + spread,
