1	// app.js - the page: sliders, the real-data menu and the two graphs.
2	// Drawing and buttons only. Every number comes from model.js (tested) or ci5.js.
3	// pageNumbers() has no drawing in it, so it can also run in node for checks.
4	
5	const MEET_AGE = 62.5; // real data is shifted to meet the model's exact line here (spec)
6	const M_PEOPLE = 20000;
7	
8	/**
9	 * Everything the page shows, for one setting. `sim` is a runReport result or null.
10	 * Returns the exact curve, the real curve (raw and shifted), the fits and the lifetime risk.
11	 */
12	function pageNumbers(r, p, N, cancerIndex, sim) {
13	  const exactGroups = expectedRates(N, r, p);
14	  const mids = (gs) => gs.map((g) => g.start + 2.5);
15	  const fromSlopeAge = (gs) => gs.filter((g) => g.start >= SLOPE_FROM && g.rate > 0);
16	  const exactUsed = fromSlopeAge(exactGroups);
17	  const exactFit = exactUsed.length >= 2 ? logLogFit(mids(exactUsed), exactUsed.map((g) => g.rate)) : null;
18	  const lifetimeRisk = exactGroups.reduce((sum, g) => sum + g.casesPerPerson, 0);
19	
20	  const cancer = CI5.cancers[cancerIndex];
21	  const realGroups = realRates(cancer.cases, CI5.personYears);
22	  const realUsed = fromSlopeAge(realGroups);
23	  const realFit = logLogFit(mids(realUsed), realUsed.map((g) => g.rate));
24	  const k = exactFit ? shiftToMeet(realFit, exactFit, MEET_AGE) : 1;
25	
26	  return {
27	    exact: exactGroups.map((g) => ({ age: g.start + 2.5, rate: g.rate })),
28	    exactFit,
29	    lifetimeRisk,
30	    cancerName: cancer.name,
31	    real: realGroups.map((g) => ({ age: g.start + 2.5, rate: g.rate, shifted: g.rate === null ? null : g.rate * k })),
32	    realFit,
33	    real6064: realGroups[12].rate,
34	    k,
35	    sim: sim ? sim.groups.map((g) => ({ age: g.start + 2.5, rate: g.simulatedRate, cases: g.simulatedCases })) : null,
36	    simFit: sim ? sim.simulatedFit : null,
37	    match: sim ? matchSummary(sim) : null,
38	  };
39	}
40	
41	/**
42	 * How well one simulation matches the exact model, from runReport's tested
43	 * z-scores (spec item 9). Colors use the decided bands: |z| below 2 plain,
44	 * 2 to 3 yellow, above 3 red. The pass line itself is not set yet (HAND CHECK 6).
45	 */
46	function matchSummary(sim) {
47	  const z = sim.zSummary;
48	  const k = z.groupsInSum;
49	  const spread = Math.sqrt(2 * k);
50	  const size = z.largest ? Math.abs(z.largest.z) : 0;
51	  const level = size > 3 ? "red" : size >= 2 ? "yellow" : "plain";
52	  const fromSlopeAge = sim.groups.filter((g) => g.start >= SLOPE_FROM);
53	  return {
54	    largest: z.largest, // {z, start, end} or null
55	    level,
56	    sumZ2: z.sumZ2,
57	    groups: k,
58	    noiseLow: k - spread,
59	    noiseHigh: k + spread,
60	    fewCases: fromSlopeAge.filter((g) => g.note === "few cases").length,
61	    impossible: sim.groups.filter((g) => g.note === "impossible: expected 0").map((g) => `${g.start}-${g.end}`),
62	  };
63	}
64	
65	// --- Drawing (SVG strings) --------------------------------------------------
66	const COLORS = { ink: "#0b0b0b", muted: "#52514e", grid: "#e6e5e0", blue: "#2a78d6", orange: "#d9822b" };
67	
68	/** Nice tick values: powers of 10 between lo and hi (log axes). */
69	function decades(lo, hi) {
70	  const out = [];
71	  for (let e = Math.floor(Math.log10(lo)); e <= Math.ceil(Math.log10(hi)); e++) out.push(10 ** e);
72	  return out;
73	}
74	
75	/** A round step size (1, 2 or 5 times a power of 10) at least as big as `raw`. */
76	function niceStep(raw) {
77	  const p = 10 ** Math.floor(Math.log10(raw));
78	  for (const m of [1, 2, 5, 10]) if (m * p >= raw) return m * p;
79	  return 10 * p;
80	}
81	
82	/** Rate per person-year as "per 100,000" text. */
83	function per100k(rate) {
84	  const v = rate * 1e5;
85	  if (v === 0) return "0";
86	  if (v >= 100) return Math.round(v).toLocaleString("en-US");
87	  if (v >= 1) return v.toFixed(1);
88	  return v.toPrecision(2);
89	}
90	
91	/** One graph. kind = "log" (log-log) or "plain". Rates are drawn per 100,000 person-years. */
92	function drawGraph(nums, kind) {
93	  const W = 560, H = 400, left = 70, right = 16, top = 40, bottom = 50;
94	  const log = kind === "log";
95	  const series = [
96	    ...nums.exact.map((d) => d.rate),
97	    ...nums.real.map((d) => d.shifted),
98	    ...(nums.sim ? nums.sim.map((d) => d.rate) : []),
99	  ].filter((v) => v !== null && v > 0).map((v) => v * 1e5);
100	  const maxV = Math.max(...series);
101	  const minV = Math.min(...series.filter((v) => v >= maxV * 1e-6)); // don't let a near-0 value squash the plot
102	  const xMin = log ? 2 : 0, xMax = log ? 100 : 85;
103	  const yMin = log ? 10 ** Math.floor(Math.log10(minV)) : 0;
104	  const step = niceStep(maxV * 1.05 / 4); // plain axis: about 4 round-number steps
105	  const yMax = log ? 10 ** Math.ceil(Math.log10(maxV)) : step * Math.ceil((maxV * 1.05) / step);
106	  const xp = (a) => left + (log ? (Math.log10(a) - Math.log10(xMin)) / (Math.log10(xMax) - Math.log10(xMin)) : (a - xMin) / (xMax - xMin)) * (W - left - right);
107	  const yp = (v) => H - bottom - (log ? (Math.log10(v) - Math.log10(yMin)) / (Math.log10(yMax) - Math.log10(yMin)) : (v - yMin) / (yMax - yMin)) * (H - top - bottom);
108	  const ok = (v) => v !== null && v > 0 && (!log || v * 1e5 >= yMin);
109	  const s = [];
110	  s.push(`<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" font-family="Helvetica, Arial, sans-serif">`);
111	  s.push(`<text x="${left}" y="24" font-size="15" font-weight="600" fill="${COLORS.ink}">${log ? "Log-log: the slope counts the hits" : "Plain axes: how fast the rate rises"}</text>`);
112	  // Ages used for the slope (25 to 85).
113	  s.push(`<rect x="${xp(25)}" y="${top}" width="${xp(85) - xp(25)}" height="${H - top - bottom}" fill="${COLORS.ink}" opacity="0.035"/>`);
114	  // Grid.
115	  for (const a of log ? [2, 5, 10, 20, 30, 50, 70, 100] : [0, 10, 20, 30, 40, 50, 60, 70, 80]) {
116	    s.push(`<line x1="${xp(a)}" y1="${top}" x2="${xp(a)}" y2="${H - bottom}" stroke="${COLORS.grid}"/>`);
117	    s.push(`<text x="${xp(a)}" y="${H - bottom + 18}" font-size="11" fill="${COLORS.muted}" text-anchor="middle">${a}</text>`);
118	  }
119	  const yTicks = log ? decades(yMin, yMax) : Array.from({ length: Math.round(yMax / step) + 1 }, (_, i) => i * step);
120	  for (const v of yTicks) {
121	    s.push(`<line x1="${left}" y1="${yp(v)}" x2="${W - right}" y2="${yp(v)}" stroke="${COLORS.grid}"/>`);
122	    s.push(`<text x="${left - 6}" y="${yp(v) + 4}" font-size="11" fill="${COLORS.muted}" text-anchor="end">${v === 0 ? 0 : v >= 1 ? Math.round(v).toLocaleString("en-US") : log ? v.toPrecision(1) : +v.toPrecision(3)}</text>`);
123	  }
124	  s.push(`<text x="${(left + W - right) / 2}" y="${H - 12}" font-size="12" fill="${COLORS.muted}" text-anchor="middle">Age${log ? " (log scale)" : ""}</text>`);
125	  s.push(`<text transform="translate(16 ${(top + H - bottom) / 2}) rotate(-90)" font-size="12" fill="${COLORS.muted}" text-anchor="middle">New cancers per 100,000 person-years${log ? " (log)" : ""}</text>`);
126	
127	  const line = (pts, color, extra) => {
128	    const xy = pts.filter((d) => ok(d.v)).map((d) => `${xp(d.a).toFixed(1)},${yp(d.v * 1e5).toFixed(1)}`);
129	    if (xy.length > 1) s.push(`<polyline fill="none" stroke="${color}" stroke-width="2" ${extra || ""} points="${xy.join(" ")}"/>`);
130	  };
131	  const dots = (pts, color, tip) => {
132	    for (const d of pts.filter((d) => ok(d.v))) {
133	      s.push(`<circle cx="${xp(d.a).toFixed(1)}" cy="${yp(d.v * 1e5).toFixed(1)}" r="4" fill="${color}" stroke="#fff" stroke-width="1.5"><title>${tip(d)}</title></circle>`);
134	    }
135	  };
136	  // Real data (shifted), orange.
137	  const real = nums.real.map((d) => ({ a: d.age, v: d.shifted, raw: d.rate }));
138	  line(real, COLORS.orange, 'stroke-opacity="0.5"');
139	  dots(real, COLORS.orange, (d) => `${nums.cancerName}, ages ${d.a - 2.5}-${d.a + 1.5}: real ${per100k(d.raw)} per 100,000 (drawn ×${nums.k.toPrecision(3)})`);
140	  // Exact curve, black.
141	  line(nums.exact.map((d) => ({ a: d.age, v: d.rate })), COLORS.ink);
142	  // Simulation, blue dots and fitted line (log graph only for the line: it is straight there).
143	  if (nums.sim) {
144	    dots(nums.sim.map((d) => ({ a: d.age, v: d.rate, cases: d.cases })), COLORS.blue,
145	      (d) => `Ages ${d.a - 2.5}-${d.a + 1.5}, all 20,000 simulated people: ${d.cases} cancers, ` +
146	        `${Math.round(d.cases / d.v).toLocaleString("en-US")} person-years, rate ${per100k(d.v)} per 100,000`);
147	    if (nums.simFit) {
148	      const f = (a) => Math.exp(nums.simFit.intercept + nums.simFit.slope * Math.log(a));
149	      const pts = [];
150	      for (let a = 27.5; a <= 82.5; a += 1) pts.push({ a, v: f(a) });
151	      line(pts, COLORS.blue, 'stroke-dasharray="6 4"');
152	    }
153	  }
154	  s.push("</svg>");
155	  return s.join("\n");
156	}
157	
158	// --- Page wiring (browser only) -----------------------------------------------
159	// The p and N sliders snap to a few round values (Cameron, 2026-11-14: fewer
160	// in-between values, so each move is a clear step). The slider gives an index.
161	const P_VALUES = [0.001, 0.002, 0.003, 0.005, 0.0075, 0.01, 0.015, 0.02];
162	const N_VALUES = [10, 25, 50, 100, 150, 200, 300, 400];
163	
164	if (typeof document !== "undefined") {
165	  const $ = (id) => document.getElementById(id);
166	  const state = { seed: 1, sim: null, simKey: null, running: false };
167	  CI5.cancers.forEach((c, i) => $("cancer").add(new Option(c.name, i)));
168	
169	  const settings = () => ({
170	    r: Number($("r").value),
171	    p: P_VALUES[Number($("p").value)],
172	    N: N_VALUES[Number($("N").value)],
173	    cancer: Number($("cancer").value),
174	  });
175	  const key = (st) => `${st.r}|${st.p}|${st.N}|${state.seed}`;
176	
177	  /** Put a number in one of the big tiles, with a smaller line under it. */
178	  function tile(id, big, small) {
179	    $(id).querySelector(".big").innerHTML = big;
180	    $(id).querySelector(".small").innerHTML = small;
181	  }
182	
183	  /** Redraw everything from the current sliders. The simulation is shown only if it matches them. */
184	  function render() {
185	    const st = settings();
186	    $("rOut").textContent = st.r;
187	    $("pOut").textContent = st.p;
188	    $("NOut").textContent = st.N;
189	    const sim = state.simKey === key(st) ? state.sim : null;
190	    const nums = pageNumbers(st.r, st.p, st.N, st.cancer, sim);
191	
192	    tile("tLife", `${(100 * nums.lifetimeRisk).toFixed(1)}%`, "chance of cancer by age 85 (real single cancers: a few % up to ~10%)");
193	    const r2 = (fit) => `R² ${fit.rSquared.toFixed(3)}`;
194	    tile("tExact", nums.exactFit ? nums.exactFit.slope.toFixed(2) : "–",
195	      nums.exactFit ? `${r2(nums.exactFit)} · simple rule says r − 1 = ${st.r - 1}` : "no cases from age 25 up");
196	    if (nums.simFit) {
197	      tile("tSim", nums.simFit.slope.toFixed(2), `${r2(nums.simFit)} · ${nums.simFit.used} age groups · 20,000 people, seed ${state.seed}`);
198	    } else {
199	      tile("tSim", "–", state.sim ? "settings changed: press Run again" : "press Run simulation");
200	    }
201	    tile("tReal", nums.realFit.slope.toFixed(2),
202	      `${r2(nums.realFit)} · ${nums.cancerName}, England men. Real 60–64 rate ${per100k(nums.real6064)} per 100,000, drawn ×${nums.k.toPrecision(3)}`);
203	    $("match").innerHTML = matchHtml(nums.match, !!state.sim);
204	
205	    $("logGraph").innerHTML = drawGraph(nums, "log");
206	    $("plainGraph").innerHTML = drawGraph(nums, "plain");
207	  }
208	
209	  /** The "how well does the simulation match?" panel, as HTML. */
210	  function matchHtml(m, ranBefore) {
211	    const passLine = `<div class="note">Pass line not set yet: how far off counts as "wrong" will be measured over 20 seeds
212	      (spec HAND CHECK 6). Until then these numbers describe the run; they don't pass or fail it.</div>`;
213	    if (!m) {
214	      return `<div class="mtitle">How well does the simulation match the exact model?</div>
215	        <div>${ranBefore ? "Settings changed: press Run simulation again." : "Press Run simulation to compare it with the exact model."}</div>${passLine}`;
216	    }
217	    const zText = m.largest
218	      ? `<b class="${m.level}">${Math.abs(m.largest.z).toFixed(2)}</b> in ages ${m.largest.start}–${m.largest.end}
219	         (${m.largest.z > 0 ? "too many" : "too few"} cases)`
220	      : "none (no age group from 25 up has enough cases)";
221	    const extra = [
222	      m.fewCases ? `${m.fewCases} group(s) from 25 up had fewer than 10 expected cases; their z is unreliable and left out.` : "",
223	      m.impossible.length ? `<b class="red">Impossible: cases in ${m.impossible.join(", ")}, where the exact model expects 0.</b>` : "",
224	    ].filter(Boolean).map((t) => `<div>${t}</div>`).join("");
225	    return `<div class="mtitle">How well does the simulation match the exact model?</div>
226	      <div><b>Largest gap (|z|):</b> ${zText}. Up to 2 is normal noise; 2–3 <span class="yellow">yellow</span>; over 3 <span class="red">red</span>.</div>
